/* dirichlet.h -- the Dirichlet character engine shared by DirichletCharacter
 * and DirichletL.
 *
 * A Dirichlet character chi mod k is labelled, as in Mathematica, by an index
 * j in 1..EulerPhi[k]. The labelling (reverse-engineered from, and checked
 * against, Mathematica 14):
 *
 *   - Factor k = prod p_i^a_i with the primes ASCENDING. (Z/kZ)^* is the direct
 *     product of the (Z/p^a)^*, and those split into cyclic COMPONENTS:
 *       odd p^a   one component, generated by the smallest primitive root g
 *                 mod p^a, of order phi(p^a);
 *       4         one component, generated by 3 (= -1), order 2;
 *       2^a, a>=3 two components: the SIGN component <-1> (order 2) and the
 *                 FIVE component <5> (order 2^(a-2)), in that order;
 *       2         none (the group is trivial).
 *   - j - 1 is written in mixed radix over the components, the FIRST component
 *     (smallest prime; SIGN before FIVE) most significant:
 *       j - 1 = sum_c d_c * prod_{c' after c} ord_c'.
 *   - chi(g_c) = exp(2 Pi I d_c / ord_c) on each component generator, and chi
 *     is the product of its components; chi(n) = 0 when gcd(n, k) > 1.
 * So j = 1 is the principal character, and for a prime k with primitive root g,
 * DirichletCharacter[k, j, g] = Exp[2 Pi I (j-1)/(k-1)].
 *
 * A table (DchTable) holds everything derived from (k, j): the components and
 * their digits, the order of chi, its parity, its conductor f and the induced
 * primitive character chi* mod f, the primes dividing k but not f (the Euler
 * factors that relate L(s, chi) to L(s, chi*)), and -- when f is small enough --
 * dense tables of chi* over 0..f-1 (exact exponents and machine re/im) plus the
 * root number of chi*. Tables are immutable once built.
 *
 * Values are roots of unity exp(2 Pi I e / ord(chi)); every routine here works
 * with the EXPONENT e in Z/ord, so nothing is rounded until a caller asks for a
 * double. All arithmetic is overflow-safe for k < 2^63.
 */
#ifndef MATHILDA_DIRICHLET_H
#define MATHILDA_DIRICHLET_H

#include <stdbool.h>
#include <stdint.h>
#include "expr.h"

/* Largest conductor for which the dense chi* tables (exponents, machine values,
 * root number) are built. Beyond it a character is still fully usable for
 * single values (discrete logs per call), but DirichletL declines numerically. */
#define DCH_TABLE_MAX ((uint64_t)1 << 22)

#define DCH_MAX_PRIMES 16      /* distinct primes of k < 2^63: at most 15 */
#define DCH_MAX_FAC    24      /* distinct primes of a component order    */

/* One cyclic component of (Z/p^a)^*. */
typedef struct {
    int      kind;          /* DCH_CYC, DCH_SIGN or DCH_FIVE                 */
    uint64_t g;             /* generator mod q (primitive root / -1 / 5)     */
    uint64_t ord;           /* order of the component group                  */
    uint64_t d;             /* this character's digit, 0 <= d < ord          */
    int      nfac;          /* prime factorisation of ord (for Pohlig-Hellman) */
    uint64_t fac_p[DCH_MAX_FAC];
    int      fac_e[DCH_MAX_FAC];
} DchComp;

enum { DCH_CYC = 0, DCH_SIGN = 1, DCH_FIVE = 2 };

/* The part of k at one prime. */
typedef struct {
    uint64_t p;             /* prime                                         */
    int      a;             /* exponent in k                                 */
    uint64_t q;             /* p^a                                           */
    int      b;             /* conductor exponent: chi's p-part has conductor p^b (0 = trivial) */
    uint64_t qb;            /* p^b                                           */
    int      ncomp;         /* 0, 1 or 2                                     */
    DchComp  comp[2];
} DchPart;

typedef struct DchTable {
    int64_t  k, j;
    int      nparts;
    DchPart  part[DCH_MAX_PRIMES];
    uint64_t order;         /* order of chi (1 = principal)                  */
    bool     principal;
    bool     real;          /* order <= 2                                    */
    int      odd;           /* delta: chi(-1) = (-1)^delta                   */
    uint64_t f;             /* conductor                                     */

    /* Euler factors: primes p | k with p not dividing f, and chi*(p) as an
     * exponent over `order`. L(s,chi) = L(s,chi*) prod (1 - chi*(p) p^-s). */
    int      neul;
    uint64_t eul_p[DCH_MAX_PRIMES];
    uint64_t eul_e[DCH_MAX_PRIMES];

    /* Dense tables over a = 0..f-1 (NULL when f > DCH_TABLE_MAX):
     * estar[a] = exponent of chi*(a) over `order`, or -1 when gcd(a, f) > 1;
     * cre/cim = chi*(a) as machine re/im (exact 0, +-1 on the axes). */
    int32_t* estar;
    double*  cre;
    double*  cim;
    /* Root number of chi*: eps = tau(chi*)/(I^odd Sqrt[f]), |eps| = 1, with
     * tau(chi*) = sum_a chi*(a) exp(2 Pi I a/f). Valid when estar != NULL. */
    double   eps_re, eps_im;
} DchTable;

/* Validate (k, j) and return the table: 1 <= j <= EulerPhi[k], k < 2^63.
 * `tables` asks for the dense chi* tables (estar / cre / cim / eps; built only
 * when f <= DCH_TABLE_MAX) -- the L-function needs them, single character
 * values do not, and building them costs O(f).
 *
 * Tables are cached (immutable once published; safe to read from the threaded
 * Compile loops). When the cache is full the table is built fresh: *owned is
 * then set and the caller must dch_free it. *owned is NULL for a cached table.
 * Returns NULL when (k, j) is out of range or the factorisation of k (or of a
 * component order) cannot be completed -- the caller leaves the call
 * unevaluated. `phi_out`, when non-NULL, receives EulerPhi[k] (also on an
 * out-of-range j, so the caller can word the `invl` message); it is 0 when k
 * itself could not be handled. */
const DchTable* dch_get(int64_t k, int64_t j, bool tables, DchTable** owned, uint64_t* phi_out);
void dch_free(DchTable* t);

/* Exponent of chi(n) over t->order; false when gcd(n, k) > 1 (chi(n) = 0). */
bool dch_exp(const DchTable* t, uint64_t n, uint64_t* e);
/* Exponent of chi*(n) (the primitive character); false when gcd(n, f) > 1. */
bool dch_star_exp(const DchTable* t, uint64_t n, uint64_t* e);

/* chi(n) for an arbitrary integer n (n reduced mod k; negative n allowed), in
 * Mathematica's normal form: 0, a unit (1, -1, I, -I), or unit * E^(I Pi r)
 * with r rational in (-1, 1) not a multiple of 1/2. The unit collects the
 * components whose value is itself a unit; the remaining components combine
 * into the single exponential, which is folded back into the unit when it
 * lands on one. Returns a new, evaluated Expr. */
Expr* dch_value_expr_mpz_mod(const DchTable* t, uint64_t n_mod_k);

/* Normal form of exp(2 Pi I num/den) times I^quarter: the unit/exponential
 * split described above. Shared with the exact DirichletL code, which renders
 * cyclotomic numbers through it. */
Expr* dch_root_of_unity_expr(int quarter, uint64_t num, uint64_t den);

/* Validate the (k, j) arguments of `res` (head[k, j, ...]) and return the
 * table, emitting Mathematica's messages: `intp` for a number that is not a
 * positive integer at position 1 or 2, `invl` for j > EulerPhi[k]. A symbolic
 * argument returns NULL silently. *owned as for dch_get. */
const DchTable* dch_validate_kj(const char* head, Expr* res, bool tables, DchTable** owned);

/* True when (k, j) are integer-literal Exprs labelling a REAL character (the
 * Compile[] type inference types DirichletL[k, j, real] as Real then). */
bool dch_labels_real(const Expr* k, const Expr* j);

/* True for an MPFR leaf; always false in a USE_MPFR=0 build, where the
 * EXPR_MPFR tag does not exist. */
static inline bool dch_is_mpfr(const Expr* e) {
#ifdef USE_MPFR
    return e->type == EXPR_MPFR;
#else
    (void)e;
    return false;
#endif
}

/* Overflow-safe modular helpers (moduli < 2^63). */
uint64_t dch_mulmod(uint64_t a, uint64_t b, uint64_t m);
uint64_t dch_powmod(uint64_t b, uint64_t e, uint64_t m);
uint64_t dch_gcd(uint64_t a, uint64_t b);

#endif /* MATHILDA_DIRICHLET_H */
